// Official individual Hisn al-Muslim recordings; lexical formula must match the displayed text.
const entries=[{"key":"before-sleep","arabic":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","url":"https://www.hisnmuslim.com/audio/ar/105.mp3"},{"key":"after-waking","arabic":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","url":"https://www.hisnmuslim.com/audio/ar/1.mp3"},{"key":"wearing-clothes","arabic":"الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","url":"https://www.hisnmuslim.com/audio/ar/5.mp3"},{"key":"before-meal","arabic":"بِسْمِ اللَّهِ","url":"https://www.hisnmuslim.com/audio/ar/9.mp3"},{"key":"after-meal","arabic":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","url":"https://www.hisnmuslim.com/audio/ar/180.mp3"},{"key":"after-toilet","arabic":"غُفْرَانَكَ","url":"https://www.hisnmuslim.com/audio/ar/11.mp3"},{"key":"after-wudu","arabic":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","url":"https://www.hisnmuslim.com/audio/ar/13.mp3"},{"key":"after-rain","arabic":"مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ","url":"https://www.hisnmuslim.com/audio/ar/173.mp3"},{"key":"when-angry","arabic":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","url":"https://www.hisnmuslim.com/audio/ar/193.mp3"},{"key":"thanking-someone","arabic":"جَزَاكَ اللَّهُ خَيْرًا","url":"https://www.hisnmuslim.com/audio/ar/198.mp3"},{"key":"leaving-gathering","arabic":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","url":"https://www.hisnmuslim.com/audio/ar/15.mp3"},{"key":"before-intimacy","arabic":"بِسْمِ اللَّهِ اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا","url":"https://www.hisnmuslim.com/audio/ar/192.mp3"},{"key":"stopping-on-journey","arabic":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","url":"https://www.hisnmuslim.com/audio/ar/216.mp3"},{"key":"help-in-worship","arabic":"اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","url":"https://www.hisnmuslim.com/audio/ar/59.mp3"},{"key":"new-garment","arabic":"اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ","url":"https://www.hisnmuslim.com/audio/ar/6.mp3"},{"key":"removing-clothes","arabic":"بِسْمِ اللَّهِ","url":"https://www.hisnmuslim.com/audio/ar/9.mp3"},{"key":"turning-at-night","arabic":"لاَ إِلَهَ إِلاَّ اللَّهُ الْوَاحِدُ الْقَهّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزيزُ الْغَفَّارُ","url":"https://www.hisnmuslim.com/audio/ar/112.mp3"},{"key":"fear-at-night","arabic":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّياطِينِ وَأَنْ يَحْضُرُونِ","url":"https://www.hisnmuslim.com/audio/ar/113.mp3"},{"key":"severe-distress","arabic":"لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","url":"https://www.hisnmuslim.com/audio/ar/122.mp3"},{"key":"hope-for-mercy","arabic":"اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لاَ إِلَهَ إِلاَّ أَنْتَ","url":"https://www.hisnmuslim.com/audio/ar/123.mp3"},{"key":"dua-of-yunus","arabic":"لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظّالِمِينَ","url":"https://www.hisnmuslim.com/audio/ar/124.mp3"},{"key":"reliance-in-distress","arabic":"اللَّهُ اللَّهُ رَبِّي لاَ أُشْرِكُ بِهِ شَيْئاً","url":"https://www.hisnmuslim.com/audio/ar/125.mp3"},{"key":"paying-debt","arabic":"اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","url":"https://www.hisnmuslim.com/audio/ar/136.mp3"},{"key":"difficult-task","arabic":"اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلاً","url":"https://www.hisnmuslim.com/audio/ar/139.mp3"},{"key":"visiting-sick","arabic":"لاَ بأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ","url":"https://www.hisnmuslim.com/audio/ar/147.mp3"},{"key":"when-calamity-strikes","arabic":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرَاً مِنْهَا","url":"https://www.hisnmuslim.com/audio/ar/154.mp3"},{"key":"strong-wind","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ","url":"https://www.hisnmuslim.com/audio/ar/167.mp3"},{"key":"asking-for-rain","arabic":"اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا","url":"https://www.hisnmuslim.com/audio/ar/170.mp3"},{"key":"heavy-rain","arabic":"اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا، اللَّهُمَّ عَلَى الآكَامِ وَالظِّرَابِ، وَبُطُونِ الْأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ","url":"https://www.hisnmuslim.com/audio/ar/174.mp3"},{"key":"breaking-fast","arabic":"ذَهَبَ الظَّمَأُ وَابْتَلَّتِ العُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","url":"https://www.hisnmuslim.com/audio/ar/176.mp3"},{"key":"for-host","arabic":"اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُم، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ","url":"https://www.hisnmuslim.com/audio/ar/182.mp3"},{"key":"for-one-who-fed","arabic":"اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي","url":"https://www.hisnmuslim.com/audio/ar/183.mp3"},{"key":"breaking-fast-with-hosts","arabic":"أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلاَئِكَةُ","url":"https://www.hisnmuslim.com/audio/ar/184.mp3"},{"key":"fasting-and-insult","arabic":"إِنِّي صَائِمٌ، إِنِّي صَائِمٌ","url":"https://www.hisnmuslim.com/audio/ar/186.mp3"},{"key":"first-fruit","arabic":"اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا","url":"https://www.hisnmuslim.com/audio/ar/187.mp3"},{"key":"for-newlyweds","arabic":"بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ","url":"https://www.hisnmuslim.com/audio/ar/190.mp3"},{"key":"love-for-allah","arabic":"أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ","url":"https://www.hisnmuslim.com/audio/ar/200.mp3"},{"key":"offered-help","arabic":"بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ","url":"https://www.hisnmuslim.com/audio/ar/201.mp3"},{"key":"returning-debt","arabic":"بارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالأَدَاءُ","url":"https://www.hisnmuslim.com/audio/ar/202.mp3"},{"key":"protection-from-shirk","arabic":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لاَ أَعْلَمُ","url":"https://www.hisnmuslim.com/audio/ar/203.mp3"},{"key":"traveler-to-those-staying","arabic":"أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لاَ تَضِيعُ وَدَائِعُهُ","url":"https://www.hisnmuslim.com/audio/ar/211.mp3"},{"key":"seeing-traveler-off","arabic":"أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ","url":"https://www.hisnmuslim.com/audio/ar/212.mp3"},{"key":"blessing-traveler","arabic":"زَوَّدَكَ اللَّهُ التَّقْوَى، وَغَفَرَ ذَنْبَكَ، وَيَسَّرَ لَكَ الخَيْرَ حَيْثُ ما كُنْتَ","url":"https://www.hisnmuslim.com/audio/ar/213.mp3"}];
export const normalizeDuaArabic=value=>String(value||'').normalize('NFKC').replace(/[\u0640\u064b-\u065f\u0670\u06d6-\u06ed]/g,'').replace(/[أإآٱ]/g,'ا').replace(/[\s\p{P}\p{N}\u200e-\u200f\u061c]/gu,'');
const recordings=new Map(entries.map(entry=>[entry.key,Object.freeze(entry)]));
export function safeDuaAudio(value){try{const url=new URL(value);return url.protocol==='https:'&&url.hostname==='www.hisnmuslim.com'&&!url.port&&/^\/audio\/ar\/\d+\.mp3$/.test(url.pathname)&&!url.username&&!url.password&&!url.search&&!url.hash?url.href:null;}catch{return null;}}
export function duaRecording(item,passage=item){const key=passage===item?item.id:item.id+':'+passage.id,recording=recordings.get(key);return recording&&safeDuaAudio(recording.url)&&normalizeDuaArabic(recording.arabic)===normalizeDuaArabic(passage.arabic)?recording:null;}
